contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: take a deposit amount and perform deposit then withdrawAll
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // record contract balance of C before operations
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        // deposit some Ether into C on behalf of this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // attempt withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read balances after the call
        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        // GENERAL RULE:
        // 1) withdrawAll never increases C's on-chain balance beyond the prior balance plus the deposit
        // 2) if withdrawAll returned (did not revert) then this contract's balance did not increase by more than depositAmount
        assert(afterCBalance <= beforeCBalance + depositAmount && (reverted || afterThisBalance <= beforeThisBalance + depositAmount));
    }

    // allow this contract to receive Ether forwarded by C
    receive() external payable { }
}

